widget.solution:
import numpy as np

def survivor_bias(r, dead_mask, J=6):
    def spread(panel):
        f = formation_returns(panel, J)
        T = panel.shape[0]
        return float(np.mean([cohort_weights(f[t]) @ panel[t]
                              for t in range(J, T)]))
    everyone = spread(r)
    survivors = spread(r[:, ~dead_mask])
    return everyone, survivors
